      SUBROUTINE THORUC---- CALCULATES THIRD-ORDER MATRIX ELEMENTS FOR A COMBINED FUNCTIONC---- BENDING MAGNETC----------------------------------------------------------------------      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4D.CIN'      INCLUDE 'COEFS.CIN'      INCLUDE 'HSINT.CIN'      INCLUDE 'HSINT3.CIN'      INCLUDE 'HPINT.CIN'      INCLUDE 'HPINT3.CIN'      INCLUDE 'H0P.CIN'      INCLUDE 'PXINT.CIN'      INCLUDE 'PCXINT.CIN'      INCLUDE 'PSXINT.CIN'      INCLUDE 'PDXINT.CIN'      INCLUDE 'PCPINT.CIN'      INCLUDE 'PSPINT.CIN'      INCLUDE 'PEYINT.CIN'      INCLUDE 'PTYINT.CIN'      INCLUDE 'PEQINT.CIN'      INCLUDE 'PTQINT.CIN'      INCLUDE 'QYINT.CIN'      INCLUDE 'QCYINT.CIN'      INCLUDE 'QSYINT.CIN'      INCLUDE 'QDYINT.CIN'      INCLUDE 'QCQINT.CIN'      INCLUDE 'QSQINT.CIN'      INCLUDE 'QEXINT.CIN'      INCLUDE 'QTXINT.CIN'      INCLUDE 'QEPINT.CIN'      INCLUDE 'QTPINT.CIN'      INCLUDE 'U.CIN'      INCLUDE 'VSINT.CIN'      INCLUDE 'VSINT3.CIN'      INCLUDE 'VPINT.CIN'      INCLUDE 'VPINT3.CIN'      INCLUDE 'WMN.CIN'      INCLUDE 'XXINT.CIN'      INCLUDE 'XCXINT.CIN'      INCLUDE 'XSXINT.CIN'      INCLUDE 'XDXINT.CIN'      INCLUDE 'XCPINT.CIN'      INCLUDE 'XSPINT.CIN'      INCLUDE 'XEYINT.CIN'      INCLUDE 'XTYINT.CIN'      INCLUDE 'XEQINT.CIN'      INCLUDE 'XTQINT.CIN'      INCLUDE 'YYINT.CIN'      INCLUDE 'YCYINT.CIN'      INCLUDE 'YSYINT.CIN'      INCLUDE 'YDYINT.CIN'      INCLUDE 'YCQINT.CIN'      INCLUDE 'YSQINT.CIN'      INCLUDE 'YEXINT.CIN'      INCLUDE 'YTXINT.CIN'      INCLUDE 'YEPINT.CIN'      INCLUDE 'YTPINT.CIN'C---------------------------------------------------------------------C      U(1,1) = - GPTB*H04*HSCCC0 - 0.5*FMTN*WMN2*H06*HSCSS0     1 - 0.5*WMN3*H08*XSPSS - TNMB*WMN*H06*XSPCC     2 + TNMB*WMN2*H08*XCXSS + 2.*TNMB**2*H06*XCXCC      U(1,2) = - 3.*GPTB*H04*HSCCS0 + FMTN*WMN*H04*HSCCS0     1 - 0.5*FMTN*WMN2*H06*HSSSS0 + TNMB*H04*XCPCC     2 - 2.*TNMB*WMN*H06*XCXCS - 2.*TNMB*WMN*H06*XSPCS     3 + TNMB*WMN2*H08*XSXSS + 4.*TNMB**2*H06*XCXCS     4 + 2.*TNMB**2*H06*XSXCC + 0.5*WMN2*H06*XCPSS     5 + WMN2*H06*XSPCS     6 + 2.*TNMB*H04*HSCSX - H04*HSCSX*WMN      U(1,3) = - 0.5*FMTN*H02*HSCCC0 - 3.*GPTB*H04*HSCSS0     1 + FMTN*WMN*H04*HSCSS0 + TNMB*H04*XCXCC     2 + 2.*TNMB*H04*XCPCS - 2.*TNMB*WMN*H06*XSXCS     3 - TNMB*WMN*H06*XSPSS + 2.*TNMB**2*H06*XCXSS     4 + 4.*TNMB**2*H06*XSXCS - WMN*H04*XCPCS     5 - 0.5*WMN*H04*XSPCC     6 + 2.*TNMB*H02*HSSX2 + H02*HSCX2      U(1,4) = - 0.5*FMTN*H02*HSCCS0 - GPTB*H04*HSSSS0     1 + TNMB*H04*XCPSS + TNMB*H04*XSXCC     2 + 2.*TNMB**2*H06*XSXSS + 0.5*H02*XCPCC      U(1,8) = - WMN*NB**2*H06*HSSCS2 + 0.5*NB**3*H06*HSCSS2     1 + TGTB*H04*HSCCC2 - NMTB*WMN*NB*H08*XEYST     2 - 2.*NMB*NB*H06*XTQCE - NB**2*TNMB*H08*XCXTT     3 + 0.5*WMN*NB**2*H08*XSPTT + WMN*NB**2*H08*XTQST     4 + 2.*NMTB*NMB*H06*XEYCE - NMTB*TNMB*H06*XCXEE     5 + 0.5*NMTB*WMN*H06*XSPEE      U(1,9) = NB**2*H04*HSCCS2 + 0.5*NB**3*H06*HSSSS2     1 + TGTB*H04*HSSCC2 + NB*NMTB*H06*XEYCT     2 - 2.*NMB*NB*H06*XTQSE - NB**2*TNMB*H08*XSXTT     3 - 0.5*NB**2*H06*XCPTT - NB**2*H06*XTQCT     4 + 2.*NMTB*NMB*H06*XEYSE - NMTB*TNMB*H06*XSXEE     5 - 0.5*NMTB*H04*XCPEE      U(1,14) = WMN*NB*H04*HSSCC2 - NB**2*H04*HSCCS2     1 - WMN*NB**2*H06*HSSSS2 + 2.*TGTB*H04*HSCCS2     2 - NMTB*WMN*NB*H08*XTYST - 2.*NMB*NB*H06*XTQCT     3 + 2.*TNMB*NB*H06*XCXET - WMN*NB*H06*XSPET     4 - WMN*NB*H06*XEQST - WMN*NB*H06*XTQSE     5 + 2.*NMTB*NMB*H06*XEYCT + 2.*NMTB*NMB*H06*XTYCE     6 - 2.*NMTB*TNMB*H06*XCXET + NMTB*WMN*H06*XSPET     7 + NMTB*WMN*H06*XEYSE + 2.*NMB*H04*XEQCE     8 + NB*H02*HSCSY - NMTB*H02*HSCSY      U(1,15) = - NB*H02*HSCCC2 + NB**2*H04*HSCSS2     1 - NB**2*H04*HSSCS2 + 2.*TGTB*H04*HSSCS2     2 + NB*NMTB*H06*XTYCT - 2.*NMB*NB*H06*XTQST     3 + 2.*TNMB*NB*H06*XSXET + NB*H04*XCPET     4 + NB*H04*XEQCT + NB*H04*XTQCE     5 + 2.*NMTB*NMB*H06*XEYST + 2.*NMTB*NMB*H06*XTYSE     6 - 2.*NMTB*TNMB*H06*XSXET - NMTB*H04*XCPET     7 - NMTB*H04*XEYCE + 2.*NMB*H04*XEQSE      U(1,17) = 0.5*NB*H02*HSCCC2 + WMN*NB*H04*HSSCS2     1 + TGTB*H04*HSCSS2 + 2.*NMTB*NMB*H06*XTYCT     2 - NMTB*TNMB*H06*XCXTT + 0.5*NMTB*WMN*H06*XSPTT     3 + NMTB*WMN*H06*XTYSE + 2.*NMB*H04*XEQCT     4 - TNMB*H04*XCXEE + 0.5*WMN*H04*XSPEE     5 + WMN*H04*XEQSE     6 - NMTB*H02*HSSY2 - H02*HSCY2      U(1,18) = - NB*H02*HSCCS2 + 0.5*NB*H02*HSSCC2     1 + TGTB*H04*HSSSS2 + 2.*NMTB*NMB*H06*XTYST     2 - NMTB*TNMB*H06*XSXTT - 0.5*NMTB*H04*XCPTT     3 - NMTB*H04*XTYCE + 2.*NMB*H04*XEQST     4 - TNMB*H04*XSXEE - 0.5*H02*XCPEE     5 - H02*XEQCE      U(1,36) = - TNMB*H03*HSCX2 - 3.*GPTB*H04*HSCCD0     1 + FMTN*WMN*H05*HSCSS0 + 1.5*WMN2*H03*HSSX2     2 - 0.5*FMTN*WMN2*H06*HSSSD0 + 2.*TNMB*TMN*H05*XCXC     3 + TNMB*TMN*H05*XXCC + TNMB*H05*XSPCC     4 - 2.*TNMB*WMN*H06*XSPCD - 2.*TNMB*WMN*H07*XCXSS     5 + TNMB*WMN2*H08*XDXSS + 4.*TNMB**2*H06*XCXCD     6 + 2.*TNMB**2*H06*XDXCC - TMN*WMN*H05*XSPC     7 + 0.5*TMN*WMN2*H07*XXSS + 1.5*WMN2*H07*XSPSS      U(1,37) = - 2.*TNMB*H03*HSCSX - 3.*WMN*H03*HSCSX     1 - FMTN*H03*HSCCS0 - 6.*GPTB*H04*HSCSD0     2 + FMTN*WMN*H04*HSCSD0 + FMTN*WMN*H05*HSSSS0     3 + 2.*TNMB*H04*XCPCD + 2.*TNMB*TMN*H05*XCXS     4 + 2.*TNMB*TMN*H05*XSXC + 2.*TNMB*TMN*H05*XXCS     5 + 2.*TNMB*H05*XCXCS + 2.*TNMB*H05*XSPCS     6 - 2.*TNMB*WMN*H06*XSPSD - 2.*TNMB*WMN*H06*XDXCS     7 - 2.*TNMB*WMN*H07*XSXSS + 4.*TNMB**2*H06*XCXSD     8 + 4.*TNMB**2*H06*XSXCD + 4.*TNMB**2*H06*XDXCS     9 + TMN*H03*XCPC - WMN*TMN*H05*XSPS     A - WMN*TMN*H05*XXCS - WMN*H05*XCPSS     B - 2.*WMN*H05*XSPCS     C + 2.*TNMB*H0*HSSDX + H0*TMN*HSSX + H03*HSCSX      U(1,38) = - TNMB*H0*HSSX2 + 1.5*H0*HSCX2     1 - 0.5*FMTN*H02*HSCCD0 - FMTN*H03*HSCSS0     2 - 3.*GPTB*H04*HSSSD0 + 2.*TNMB*H04*XCPSD     3 + TNMB*H04*XDXCC + 2.*TNMB*TMN*H05*XSXS     4 + TNMB*TMN*H05*XXSS + 2.*TNMB*H05*XSXCS     5 + TNMB*H05*XSPSS + 4.*TNMB**2*H06*XSXSD     6 + 2.*TNMB**2*H06*XDXSS + TMN*H03*XCPS     7 + 0.5*TMN*H03*XXCC + H03*XCPCS     8 + 0.5*H03*XSPCC      U(1,41) = NB**2*H05*HSSCS2 + 0.5*NB**2*H03*HSSY2     1 + 0.5*NB**3*H06*HSDSS2 + 0.5*NMTB*H03*HSCY2     2 + TGTB*H04*HSDCC2 - NB*NMTB*H05*XEYE     3 + NB*NMTB*H07*XEYST - 2.*NMB*NB*H06*XTQDE     4 - NB**2*TNMB*H08*XDXTT + NB**2*H05*XTQE     5 - 0.5*TMN*NB**2*H07*XXTT - 0.5*NB**2*H07*XSPTT     6 - NB**2*H07*XTQST + 2.*NMTB*NMB*H06*XEYDE     7 - NMTB*TNMB*H06*XDXEE - 0.5*NMTB*TMN*H05*XXEE     8 - 0.5*NMTB*H05*XSPEE      U(1,44) = - NB*H03*HSSCC2 - NB*H0*HSCSY     1 - NB**2*H04*HSDCS2 + NB**2*H05*HSSSS2     2 + NMTB*H0*HSCSY + 2.*TGTB*H04*HSDCS2     3 - NB*NMTB*H05*XEYT - NMTB*NB*H05*XTYE     4 + NMTB*NB*H07*XTYST - 2.*NMB*NB*H06*XTQDT     5 + 2.*TNMB*NB*H06*XDXET - NB*H03*XEQE     6 + TMN*NB*H05*XXET + NB*H05*XSPET     7 + NB*H05*XEQST + NB*H05*XTQSE     8 + NB**2*H05*XTQT + 2.*NMTB*NMB*H06*XEYDT     9 + 2.*NMTB*NMB*H06*XTYDE - 2.*NMTB*TNMB*H06*XDXET     A - NMTB*TMN*H05*XXET - NMTB*H05*XSPET     B - NMTB*H05*XEYSE + 2.*NMB*H04*XEQDE      U(1,45) = 0.5*NB*H02*HSDCC2 - NB*H03*HSSCS2     1 + 0.5*NMTB*H0*HSSY2 + 0.5*H0*HSCY2     2 + TGTB*H04*HSDSS2 - NB*NMTB*H05*XTYT     3 - NB*H03*XEQT + 2.*NMTB*NMB*H06*XTYDT     4 - NMTB*TNMB*H06*XDXTT - 0.5*NMTB*TMN*H05*XXTT     5 - 0.5*NMTB*H05*XSPTT - NMTB*H05*XTYSE     6 + 2.*NMB*H04*XEQDT - TNMB*H04*XDXEE     7 - 0.5*TMN*H03*XXEE - 0.5*H03*XSPEE     8 - H03*XEQSE      U(1,51) = - 2.*TNMB*H02*HSCDX - TMN*H02*HSCX     1 - 0.5*FMTN*H04*HSCSS0 - 3.*GPTB*H04*HSCDD0     2 - 3.*WMN*H02*HSSX2 + FMTN*WMN*H05*HSSSD0     3 - 2.*TNMB*H04*XCXI + 2.*TNMB*TMN*H05*XCXD     4 + 2.*TNMB*TMN*H05*XDXC + 2.*TNMB*TMN*H05*XXCD     5 + 2.*TNMB*H05*XSPCD + TNMB*H06*XCXSS     6 - TNMB*WMN*H06*XSPDD - 2.*TNMB*WMN*H07*XDXSS     7 + 2.*TNMB**2*H06*XCXDD + 4.*TNMB**2*H06*XDXCD     8 + TMN*H04*XSPC + TMN**2*H04*XXC     9 + WMN*H04*XSPI - TMN*WMN*H05*XSPD     A - TMN*WMN*H06*XXSS - 1.5*WMN*H06*XSPSS      U(1,52) = - 2.*TNMB*HSSDX - TMN*HSSX     1 + 3.*H02*HSCSX - FMTN*H03*HSCSD